"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9070],{3006:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainShieldGuiController","desc":"Drives the diegetic `TrainShieldGui` SurfaceGui on each tagged\\n`TrainShieldMonitor` part. Discovers monitors via CollectionService, clones\\nthe `GuiAssets.TrainShieldGui` template onto each (client-locally, so every\\nplayer drives an independent copy on the shared surface), and updates two\\nreadouts on its CRT face each frame from `TrainStateCache`: the train\\nshield (Online/Critical, eased toward `TrainStateCache.ShieldFraction()`)\\nand the train fuel reserve (`TrainStateCache.PredictedFuel()`, mirroring\\nthe on-screen fuel HUD). This controller holds no fallback snapshot of its\\nown; while the cache has none yet, both readouts show a placeholder\\ninstead of a guess. Each monitor owns a Janitor that destroys its clone\\nand disconnects its render loop when the tag is removed.","realm":["Client"],"source":{"line":19,"path":"src/StarterPlayer/StarterPlayerScripts/TrainShieldGuiController.client.luau"}}')}}]);